(() => {
  const g = __rhf.game;
  g.state.settings.autoQuality = false;
  g.setQuality('low');
  g.bears.directorT = 1e9;
  g.env.timeScale = 0;
  g.env.setTime(14);
  const w = g.env.weather;
  w.rain = w.rainTarget = 0;
  w.cloud = w.cloudTarget = 0.2;
  w.timer = 1e9;
  g.hud.firstShown = -1000;
  g.hud.hint('', 0);
  __rhf.god(true);
  // the slow test renderer never finishes a style transition before a
  // picture: show the messages where they end up
  const st = document.createElement('style');
  st.textContent = '#toasts { transition: none !important; }';
  document.head.appendChild(st);
  window.__until = async (fn, ms = 240000) => {
    const t0 = performance.now();
    while (performance.now() - t0 < ms) {
      const r = fn();
      if (r) return r;
      await new Promise((q) => setTimeout(q, 200));
    }
    return null;
  };
  // stand somewhere and face something, with the ground detail finished
  window.__stand = (x, z, lookX, lookZ, pitch = 0) => {
    const P = g.player;
    P.place(x, z, Math.atan2(-(lookX - x), -(lookZ - z)));
    P.pitch = pitch;
    __rhf.settle();
  };
  window.__ia = () => (g.interaction ? g.interaction.label : '-') + ' / ' + (g.interaction2 ? g.interaction2.label : '-');
  return 'set up; secret parts: ' + Object.keys(g.props.secret).join(', ') + '; flags ' + JSON.stringify(g.state.flags);
})()

(() => {
    const g = __rhf.game;
    g.state.flags.glider = true;
    g.state.flags.key = true;
    const ch = g.props.secret.chest;
    let best = null;
    for (let a = 0; a < 64; a++) {
      const x = ch.x + Math.cos(a / 64 * Math.PI * 2) * 1.5;
      const z = ch.z + Math.sin(a / 64 * Math.PI * 2) * 1.5;
      const d = g.colliders.deckAt(x, z, 1e9, 1e9);
      if (d !== null && Math.abs(d - ch.y) < 0.05) { best = { x, z }; break; }
    }
    __stand(best.x, best.z, ch.x, ch.z, -0.35);
    return 'with the key on the shelf: actions ' + __ia() + ', money ' + g.state.money;
  })()

(() => {
    const g = __rhf.game;
    const S = g.secret;
    const at = S.glint.position;
    // hold the flash at its peak for the picture
    const up = S.update.bind(S);
    S.update = (dt) => { S.t = 0.5 / 0.37 - dt; up(dt); };
    const f = g.world.place('landing');
    const P = g.player;
    P.place(f.x, f.z, 0);
    const dx = at.x - P.pos.x, dz = at.z - P.pos.z;
    P.yaw = Math.atan2(-dx, -dz) - 0.06;
    P.pitch = Math.atan2(at.y - (P.pos.y + 1.66), Math.hypot(dx, dz)) - 0.02;
    document.getElementById('crosshair').style.visibility = 'hidden';
    __rhf.settle();
    return 'looking from Hotrod Landing at the summit (the glint left of the middle), ' + Math.hypot(dx, dz).toFixed(0) + ' m away, ' + (at.y - P.pos.y).toFixed(0) + ' m up';
  })()

(() => {
    const g = __rhf.game;
    g.player.tool = 'camera';
    g.viewmodel.setTool('none');
    while (g.photo.zoom !== 8) g.photo.zoomIndex = (g.photo.zoomIndex + 1) % 4;
    const at = g.secret.glint.position;
    const P = g.player;
    const dx = at.x - P.pos.x, dz = at.z - P.pos.z;
    P.yaw = Math.atan2(-dx, -dz) - 0.012;
    P.pitch = Math.atan2(at.y - (P.pos.y + 1.66), Math.hypot(dx, dz)) - 0.006;
    return 'camera up at ' + g.photo.zoom + 'x, the glint a little left of the middle';
  })()

(() => {
